// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        try c.sendTo(address(0xdead), amount) { } catch { }
        uint256 balanceAfter = address(c).balance;
        bool callerIsOwner = (actor == address(this));
        assertTrue(!callerIsOwner ? balanceAfter == balanceBefore : true);
    }
}
